package com.veridoc.ai.evaluation;

/**
 * One declared turn that precedes a case's {@code question}.
 *
 * <p>Only prior <em>user</em> turns are replayable through the production HTTP
 * API: assistant replies are generated by the system at runtime and are
 * therefore never declared in the dataset. A declared {@code assistant} turn
 * would be silently ignored by the harness, so validation rejects it rather
 * than letting the dataset drift out of sync with what is actually executed.
 */
public record HistoryTurn(String role, String content) {

    public static final String USER = "user";
    public static final String ASSISTANT = "assistant";

    public static HistoryTurn user(String content) {
        return new HistoryTurn(USER, content);
    }

    public boolean isUser() {
        return USER.equals(role);
    }
}
